package com.finsightai.exception;import com.finsightai.dto.ApiError;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.Instant;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiError>validation(MethodArgumentNotValidException e,HttpServletRequest r){String m=e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).findFirst().orElse("Validation failed");return ResponseEntity.badRequest().body(new ApiError(Instant.now(),400,"Validation Error",m,r.getRequestURI()));}@ExceptionHandler(Exception.class)ResponseEntity<ApiError>generic(Exception e,HttpServletRequest r){return ResponseEntity.status(500).body(new ApiError(Instant.now(),500,"Internal Error",e.getMessage(),r.getRequestURI()));}}
